mapper.select:
select from wms_warehouse
and warehouse_code like concat('%', #{warehouseCode}, '%') and warehouse_name like concat('%', #{warehouseName}, '%') and manager like concat('%', #{manager}, '%') and status = #{status}
order by warehouse_code

mapper.update:
update wms_warehouse

    warehouse_code = #{warehouseCode}, warehouse_name = #{warehouseName}, address = #{address},
    manager = #{manager}, phone = #{phone}, status = #{status}, update_by = #{updateBy},
    update_time = sysdate(), remark = #{remark}

where warehouse_id = #{warehouseId}
